add_filter( 'woocommerce_is_purchasable', 'perfectpixel_free_products_logged_in_only', 20, 2 );
add_action( 'woocommerce_single_product_summary', 'perfectpixel_free_products_login_link', 31 );

function perfectpixel_is_free_product( $product ) {
	return $product && '' !== $product->get_price() && 0.0 === (float) $product->get_price();
}

function perfectpixel_free_products_logged_in_only( $purchasable, $product ) {
	return ( ! is_user_logged_in() && perfectpixel_is_free_product( $product ) ) ? false : $purchasable;
}

function perfectpixel_free_products_login_link() {
	global $product;
	if ( ! is_user_logged_in() && perfectpixel_is_free_product( $product ) ) {
		$url = add_query_arg( 'redirect_to', rawurlencode( get_permalink( $product->get_id() ) ), wc_get_page_permalink( 'myaccount' ) );
		echo '<p><a class="button" href="' . esc_url( $url ) . '">' . esc_html( '{{free_login_text}}' ) . '</a></p>';
	}
}
